def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg}
    unseen=set(pts); comps=[]
    while unseen:
        st=unseen.pop();q=[st];co={st}
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:unseen.remove(p);q.append(p);co.add(p)
        comps.append(co)
    motif=max(comps,key=len)
    # pattern anchor is the uniquely occurring color in motif (or central marker)
    vals={grid[r][c] for r,c in motif}
    counts={v:sum(grid[r][c]==v for r,c in motif) for v in vals}
    anchor_color=min(vals,key=lambda v:counts[v])
    ar,ac=next((r,c) for r,c in motif if grid[r][c]==anchor_color)
    offsets=[(r-ar,c-ac,grid[r][c]) for r,c in motif]
    markers=[p for co in comps if co!=motif for p in co]
    out=[row[:] for row in grid]
    for r,c in markers:
        for dr,dc,v in offsets:
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w:out[rr][cc]=v
    return out
